CSS = '''
@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=Noto+Sans+Arabic:wght@400;600;700&display=swap');
:root{color-scheme:light;--ink:#142d4e;--green:#42a884;--muted:#667685;}
body,.gradio-container{background:#f7faf8!important;}
.gradio-container{max-width:1120px!important;width:100%!important;min-width:0!important;margin:auto!important;padding:20px clamp(16px,3vw,38px) 30px!important;box-sizing:border-box!important;}
.gradio-container *{font-family:Manrope,'Noto Sans Arabic',sans-serif;box-sizing:border-box;}.gradio-container>main{padding:0!important;min-width:0!important;width:100%!important;}
.topbar{align-items:center!important;gap:12px!important;padding:0 0 18px!important;margin-bottom:8px!important;border-bottom:1px solid #dfe7e2;}.brand{display:flex;align-items:center;gap:7px;height:60px;}.brand img{width:76px;height:58px;object-fit:contain;mix-blend-mode:multiply;}.brand strong{font-size:23px;letter-spacing:-.8px;display:block;color:#142d4e;}.brand strong span{font-size:24px;margin-left:8px;font-family:'Noto Sans Arabic',sans-serif;}.tagline{font-family:'Noto Sans Arabic',sans-serif;color:#42a884;font-size:12px;display:block;margin-top:1px;}.nav-button{border:0!important;background:transparent!important;box-shadow:none!important;color:#667685!important;font-size:12px!important;min-width:fit-content!important;padding:10px!important;}.nav-button:hover{color:#142d4e!important;background:#eaf1ec!important;}
.page{border:none!important;background:transparent!important;box-shadow:none!important;padding:0!important;gap:16px!important;}.intro{padding:10px 0 12px;}.intro h1,.result-intro h1{font-size:36px!important;line-height:1.2!important;letter-spacing:-1.3px!important;color:#142d4e!important;font-weight:800!important;margin:12px 0!important;}.intro p,.result-intro>p{font-size:15px;line-height:1.7;color:#667685;max-width:650px;margin:0;}.home-intro{padding-top:24px;padding-bottom:18px;}
.exercise-card{display:grid;grid-template-columns:38% 1fr;border-radius:22px;overflow:hidden;background:#fff;border:1px solid #e1e9e3;min-height:295px;}.exercise-art{background:#eaf3ee;display:flex;align-items:center;justify-content:center;}.exercise-art img{width:100%;height:295px;object-fit:contain;mix-blend-mode:multiply;}.exercise-copy{padding:36px 35px;}.plan-tag{color:#2a8566;font-size:12px;font-weight:700;}.exercise-copy h2{font-size:34px;font-weight:800;letter-spacing:-1px;margin:11px 0;color:#142d4e;}.exercise-copy>p{font-size:14px;color:#667685;line-height:1.7;}.exercise-meta{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0;}.exercise-meta span{font-size:12px;padding:7px 10px;background:#edf4ef;color:#37644e;border-radius:6px;}.quiet{font-size:12px!important;line-height:1.6!important;color:#718077!important;max-width:440px;}.home-actions{padding-top:2px;}.home-note{text-align:center;color:#7b8780;font-size:12px;margin:0 0 12px;}
button.primary{background:#142d4e!important;color:#fff!important;border:1px solid #142d4e!important;box-shadow:none!important;}button.primary:hover{background:#204464!important;}button.secondary{background:#fff!important;color:#142d4e!important;border:1px solid #d5dfd8!important;box-shadow:none!important;}button.lg{border-radius:12px!important;min-height:54px!important;font-size:15px!important;font-weight:700!important;}.block{box-shadow:none!important;}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #42a884!important;outline-offset:3px;}
.steps{display:flex;gap:26px;padding:18px 0 4px;}.steps span{display:flex;align-items:center;gap:8px;font-size:12px;color:#7d8981;}.steps b{display:inline-grid;place-items:center;width:25px;height:25px;border:1px solid #dce5df;border-radius:50%;font-size:11px;font-weight:600;}.steps .active{color:#142d4e;font-weight:700;}.steps .active b{background:#142d4e;border-color:#142d4e;color:#fff;}
.stage-label{display:flex;align-items:center;gap:10px;font-size:14px;color:#142d4e;margin:0 0 10px;}.stage-label b{display:inline-grid;place-items:center;background:#e4f1e9;color:#328264;width:28px;height:28px;border-radius:8px;font-size:12px;}.recording-stage{gap:24px!important;}.recording-stage>.column{background:white!important;border:1px solid #dfe8e2!important;border-radius:18px;padding:18px!important;}.guide-note{margin:0 4px;}.record-hint{font-size:12px;line-height:1.7;color:#667685;margin:2px 0;}.source-toggle label{border-radius:8px!important;font-size:12px!important;}.source-toggle{padding:0!important;border:0!important;background:transparent!important;}
.feedback-page{max-width:780px;margin:0 auto!important;}.result-intro{text-align:center;margin:12px 0 22px;}.result-intro>p{margin:auto;}.complete-mark{display:grid;place-items:center;color:white;background:#42a884;border-radius:50%;width:46px;height:46px;font-size:25px;margin:22px auto 18px;}.example-label{font-size:12px!important;color:#966f35!important;}.result-numbers{display:grid;grid-template-columns:1fr 1fr;background:#fff;border:1px solid #dfe8e2;border-radius:18px;overflow:hidden;}.result-numbers>div{text-align:center;padding:26px 16px;}.result-numbers>div+div{border-left:1px solid #e3ebe5;}.result-numbers strong{display:block;color:#142d4e;font-size:47px;line-height:1.2;letter-spacing:-2px;font-weight:800;}.result-numbers small{font-size:19px;color:#91a096;letter-spacing:-.5px;}.result-numbers span{display:block;font-size:12px;color:#667685;margin-top:8px;}.score-note{text-align:center;font-size:11px;line-height:1.7;color:#78877d;padding:0 12px;margin:12px 0 25px;}.feedback-list{display:grid;gap:12px;}.feedback-item{position:relative;background:white;border:1px solid #dfe8e2;border-radius:14px;padding:20px 23px;}.feedback-item h3{font-size:16px;color:#142d4e;font-weight:700;margin:0 90px 8px 0;}.feedback-item p{font-size:13px;color:#667685;line-height:1.7;margin:6px 0;}.feedback-item .cue{color:#2c8163;}.moment{position:absolute;right:20px;top:23px;color:#688271;font-size:11px;}
.measurements{display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border:1px solid #dfe8e2;border-radius:12px;overflow:hidden;}.measurements>div{padding:20px;border-right:1px solid #e2eae4;}.measurements strong{display:block;font-size:28px;color:#142d4e;font-weight:700;}.measurements span{font-size:11px;color:#667685;}.session-summary{background:white;padding:24px;border:1px solid #dfe8e2;border-radius:14px;line-height:1.8;color:#536773;}.session-summary h3{color:#142d4e;font-size:17px;font-weight:700;margin:14px 0 8px;}.session-summary [dir=rtl]{border-top:1px solid #e0e9e3;margin-top:18px;padding-top:6px;}.source-badge{color:#328264;font-size:12px;font-weight:700;}.measurement-note{font-size:12px;color:#718077;}.feedback-copy{white-space:pre-wrap;}.observation-list{padding-left:20px;}.observation-list li{margin:12px 0;}.cue{color:#328264;}.review-note{background:#f7f3e9;border-left:3px solid #ba985d;padding:18px 20px;border-radius:4px;color:#715d37;line-height:1.75;}.review-note h3{font-size:15px;font-weight:700;}.review-note p,.review-note li{font-size:12px;margin:6px 0;}.footer{display:flex;justify-content:space-between;gap:16px;font-size:10px;color:#829087;padding:24px 0 4px;margin-top:25px;border-top:1px solid #dfe7e2;}.gradio-container footer{display:none!important;}
@media(max-width:700px){.row{flex-direction:column!important;min-width:0!important;}.column,.block,.tabs,.tabitem{min-width:0!important;max-width:100%!important;}.topbar{flex-direction:row!important;flex-wrap:wrap!important;gap:2px!important;}.topbar>.column{flex:1 0 100%!important;width:100%!important;min-width:0!important;}.topbar .nav-button{flex:1 1 45%!important;width:45%!important;min-width:0!important;}button.lg{width:100%!important;}.brand{height:52px;}.brand img{width:66px;height:50px;}.brand strong{font-size:21px;}.intro h1,.result-intro h1{font-size:28px!important;}.intro p{font-size:13px;}.exercise-card{grid-template-columns:1fr;}.exercise-art img{height:200px;}.exercise-copy{padding:24px;}.exercise-copy h2{font-size:28px;}.exercise-meta{margin:15px 0;}.exercise-meta span{font-size:11px;}.steps{gap:12px;justify-content:space-between;}.steps span{font-size:10px;gap:5px;}.steps b{width:21px;height:21px;}.recording-stage{gap:14px!important;}.recording-stage>.column{padding:13px!important;}.result-numbers strong{font-size:39px;}.result-numbers>div{padding:24px 10px;}.result-numbers span{font-size:11px;}.feedback-item{padding:18px;}.feedback-item h3{font-size:14px;}.moment{top:21px;right:16px;font-size:10px;}.measurements{grid-template-columns:1fr 1fr;}.measurements>div{padding:14px;}.footer{flex-direction:column;gap:4px;}.session-summary{padding:18px;}.tab-container{flex-wrap:wrap!important;height:auto!important;}.tab-container>button{font-size:12px!important;}.home-intro{padding-top:12px;}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;}}
'''
